{
  "name": "@trustchat/opencode-provider",
  "version": "0.3.2",
  "description": "OpenCode V2 plugin for the TrustChat OpenAI-compatible provider.",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts"
  },
  "main": "./v1-unsupported.ts",
  "files": [
    "index.ts",
    "models-dev.ts",
    "v1-unsupported.ts",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=22.18.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-provider",
    "trustchat",
    "openai-compatible",
    "llm"
  ],
  "sideEffects": false,
  "scripts": {
    "check": "node --input-type=module -e \"const m = await import('./index.ts'); const shim = await import('./v1-unsupported.ts'); if (typeof m.default?.setup !== 'function' || typeof m.default?.server !== 'function') { console.error('plugin default export with setup()/server() not found'); process.exit(1) } if (typeof shim.default !== 'function') { console.error('v1 shim default export is not a function'); process.exit(1) }\"",
    "test": "node --test models-dev.test.ts index.test.ts",
    "prepublishOnly": "npm run check && npm test"
  },
  "publishConfig": {
    "access": "public"
  }
}
